import { login, api, rec, IDS, schedule, isErr } from './zz-grader-lib.mjs'
const { toks } = await login()
const eqKeys = (o, keys) => o && JSON.stringify(Object.keys(o).sort()) === JSON.stringify([...keys].sort())
// ---- 1. seed
const r = await api('GET', `/api/leases/${IDS.lAisyah}`, toks.aisyah)
rec('1.1 GET aisyah lease as aisyah 200', r.status === 200, String(r.status))
const j = r.json
console.log('AISYAH_JSON ' + JSON.stringify(j))
rec('1.2 top-level keys', eqKeys(j, ['lease','invoices','payments']), Object.keys(j||{}).join(','))
rec('1.3 lease shape', eqKeys(j.lease, ['id','unitId','tenantId','startDate','endDate','monthlyRentSen','depositSen']) && j.lease.id===IDS.lAisyah && j.lease.unitId===IDS.unitA && j.lease.tenantId===IDS.tAisyah && j.lease.startDate==='2026-01-31' && j.lease.endDate==='2026-07-15' && j.lease.monthlyRentSen===150000 && j.lease.depositSen===300000, JSON.stringify(j.lease))
const exp = schedule({ startDate:'2026-01-31', endDate:'2026-07-15', monthlyRentSen:150000, depositSen:300000 })
const paidExp = [300000,150000,50000,0,0,0,0]
const statExp = ['paid','paid','overdue','overdue','overdue','overdue','overdue']
let ok = j.invoices.length === exp.length
j.invoices.forEach((inv, i) => {
  const e = exp[i]; if (!e) { ok = false; return }
  const keysOk = eqKeys(inv, ['id','kind','periodIndex','periodStart','periodEnd','dueDate','amountSen','paidSen','status'])
  const m = keysOk && ['kind','periodIndex','periodStart','periodEnd','dueDate','amountSen'].every(k => inv[k] === e[k]) && inv.paidSen === paidExp[i] && inv.status === statExp[i] && typeof inv.id === 'string'
  if (!m) { ok = false; console.log('MISMATCH', i, JSON.stringify(inv), JSON.stringify(e)) }
})
rec('1.4 aisyah invoices = worked example + paidSen + statuses', ok)
const p = j.payments
