import { login, api, rest, rec, IDS, isErr } from './zz-grader-lib.mjs'
import { writeFileSync } from 'node:fs'
const { toks, clients } = await login()
const L = IDS.lProbe
const get = async () => (await api('GET', `/api/leases/${L}`, toks.manager)).json
const state = async () => {
  const j = await get()
  const total = j.invoices.reduce((s, i) => s + i.amountSen, 0)
  const paid = j.invoices.reduce((s, i) => s + i.paidSen, 0)
  const pending = j.payments.filter(p => p.status === 'pending_verification').reduce((s, p) => s + p.amountSen, 0)
  return { j, total, paid, pending, cap: total - paid - pending }
}
const pay = (tok, body) => api('POST', `/api/leases/${L}/payments`, tok, body)
const RA = '2026-10-20T09:00:00+08:00'
const allocs = async pid => (await rest('GET', `payment_allocations?select=invoice_id,amount_sen&payment_id=eq.${pid}&order=amount_sen`, toks.manager)).json
const uploaded = []

let s = await state()
rec('4.0 probe lease starts clean', s.total === 2800000 && s.paid === 0 && s.pending === 0, JSON.stringify({ total: s.total, paid: s.paid, pending: s.pending }))
// a) manager cash approved immediately; allocation order
let r = await pay(toks.manager, { amountSen: 450000, method: 'cash', receivedAt: RA })
rec('4.1 manager cash -> 201 {id,status:approved}', r.status === 201 && r.json?.status === 'approved' && typeof r.json?.id === 'string', `${r.status} ${r.text}`)
const pMgr = r.json?.id
s = await state()
const inv = s.j.invoices
rec('4.2 allocation: deposit before rent on same due date, earliest first', inv[0].kind === 'deposit' && inv[0].paidSen === 400000 && inv[1].periodIndex === 0 && inv[1].paidSen === 50000 && inv.slice(2).every(i => i.paidSen === 0) && inv[0].status === 'paid' && inv[1].status === 'overdue', inv.slice(0, 3).map(i => `${i.kind}${i.periodIndex ?? ''}:${i.paidSen}:${i.status}`).join(' '))
// b) concurrent staff payments
const rem = s.cap
const a = Math.floor(rem / 2) + 1000
let rs = await Promise.all([pay(toks.staff, { amountSen: a, method: 'cash', receivedAt: RA }), pay(toks.staff, { amountSen: a, method: 'cash', receivedAt: RA })])
const st = rs.map(x => x.status).sort()
rec(`4.3 two concurrent staff payments of ${a} (cap ${rem}) -> one 201 pending + one 422`, JSON.stringify(st) === '[201,422]' && rs.find(x => x.status === 201)?.json?.status === 'pending_verification', rs.map(x => `${x.status} ${x.text}`).join(' || '))
const pStaff = rs.find(x => x.status === 201)?.json?.id
s = await state()
rec('4.4 exactly one pending payment exists', s.j.payments.filter(p => p.status === 'pending_verification').length === 1 && s.paid === 450000, `pending=${s.pending} paid=${s.paid}`)
// cap includes pending
r = await pay(toks.staff, { amountSen: s.cap + 1, method: 'cash', receivedAt: RA }); rec('4.5 staff cap+1 (cap counts pending) -> 422', r.status === 422 && isErr(r), `${r.status} ${r.text}`)
r = await pay(toks.manager, { amountSen: s.cap + 1, method: 'cash', receivedAt: RA }); rec('4.5b manager cap+1 -> 422', r.status === 422 && isErr(r), `${r.status} ${r.text}`)
// d) concurrent approve
rs = await Promise.all([api('POST', `/api/payments/${pStaff}/approve`, toks.manager, {}), api('POST', `/api/payments/${pStaff}/approve`, toks.manager, {})])
rec('4.6 concurrent approve x2 -> one 200 {status:approved} + one 409', JSON.stringify(rs.map(x => x.status).sort()) === '[200,409]' && rs.find(x => x.status === 200)?.json?.status === 'approved', rs.map(x => `${x.status} ${x.text}`).join(' || '))
s = await state()
const al = await allocs(pStaff)
rec('4.7 approved once: paidSen grew by exactly a; allocations sum = a', s.paid === 450000 + a && al.reduce((t, x) => t + x.amount_sen, 0) === a, `paid=${s.paid} expected=${450000 + a} allocRows=${al.length}`)
// earliest-first fill check after the second payment
let left = 450000 + a, okFill = true
for (const i of s.j.invoices) { const e = Math.min(i.amountSen, left); left -= e; if (i.paidSen !== e) { okFill = false } }
rec('4.8 invoices filled earliest-first after second payment', okFill, s.j.invoices.map(i => i.paidSen).join(','))
// e) reject
r = await pay(toks.staff, { amountSen: 1000, method: 'cash', receivedAt: RA }); const pRej = r.json?.id
rec('4.9 staff 1000 -> 201 pending', r.status === 201 && r.json?.status === 'pending_verification', r.text)
r = await api('POST', `/api/payments/${pRej}/reject`, toks.manager, { reason: 'abc' }); rec('4.10 reject reason "abc" -> 400', r.status === 400 && isErr(r), `${r.status} ${r.text}`)
r = await api('POST', `/api/payments/${pRej}/reject`, toks.manager, { reason: '  ab   ' }); rec('4.10b reject reason whitespace-padded "ab" -> 400', r.status === 400 && isErr(r), `${r.status} ${r.text}`)
r = await api('POST', `/api/payments/${pRej}/reject`, toks.manager, {}); rec('4.10c reject missing reason -> 400', r.status === 400 && isErr(r), `${r.status} ${r.text}`)
r = await api('POST', `/api/payments/${pRej}/reject`, toks.staff, { reason: 'Slip does not match' }); rec('4.10d staff reject -> 403', r.status === 403, `${r.status} ${r.text}`)
r = await api('POST', `/api/payments/${pRej}/reject`, toks.manager, { reason: 'Slip does not match' }); rec('4.11 reject good reason -> 200 {status:rejected}', r.status === 200 && r.json?.status === 'rejected', `${r.status} ${r.text}`)
r = await api('POST', `/api/payments/${pRej}/reject`, toks.manager, { reason: 'Slip does not match' }); rec('4.12 reject again -> 409', r.status === 409 && isErr(r), `${r.status} ${r.text}`)
r = await api('POST', `/api/payments/${pRej}/approve`, toks.manager, {}); rec('4.12b approve rejected -> 409', r.status === 409 && isErr(r), `${r.status} ${r.text}`)
r = await api('POST', `/api/payments/${pRej}/void`, toks.manager, { reason: 'some reason' }); rec('4.12c void rejected -> 409', r.status === 409 && isErr(r), `${r.status} ${r.text}`)
// f) void
const before = await state()
const alStaffBefore = JSON.stringify(await allocs(pStaff))
r = await api('POST', `/api/payments/${pMgr}/void`, toks.manager, { reason: 'abc' }); rec('4.13 void reason "abc" -> 400', r.status === 400 && isErr(r), `${r.status} ${r.text}`)
r = await api('POST', `/api/payments/${pMgr}/void`, toks.staff, { reason: 'Wrong lease entry' }); rec('4.13b staff void -> 403', r.status === 403, `${r.status} ${r.text}`)
r = await api('POST', `/api/payments/${pMgr}/void`, toks.manager, { reason: 'Wrong lease entry' }); rec('4.14 void approved -> 200 {status:voided}', r.status === 200 && r.json?.status === 'voided', `${r.status} ${r.text}`)
const after = await state()
const alMgrAfter = await allocs(pMgr)
const alStaffAfter = JSON.stringify(await allocs(pStaff))
const diffs = before.j.invoices.map((i, k) => i.paidSen - after.j.invoices[k].paidSen)
rec('4.15 void removes only its allocations (deposit -400000, p0 -50000, others unchanged)', diffs[0] === 400000 && diffs[1] === 50000 && diffs.slice(2).every(d => d === 0) && alMgrAfter.length === 0 && alStaffBefore === alStaffAfter && after.j.payments.find(p => p.id === pMgr)?.status === 'voided', `diffs=${diffs.join(',')} mgrAllocsLeft=${alMgrAfter.length} staffAllocsSame=${alStaffBefore === alStaffAfter}`)
r = await api('POST', `/api/payments/${pMgr}/void`, toks.manager, { reason: 'Wrong lease entry' }); rec('4.16 void again -> 409', r.status === 409 && isErr(r), `${r.status} ${r.text}`)
r = await api('POST', `/api/payments/${pMgr}/approve`, toks.manager, {}); rec('4.16b approve voided -> 409', r.status === 409 && isErr(r), `${r.status} ${r.text}`)
// g) void pending
r = await pay(toks.staff, { amountSen: 2000, method: 'cash', receivedAt: RA }); const pPend = r.json?.id
r = await api('POST', `/api/payments/${pPend}/void`, toks.manager, { reason: 'some reason' }); rec('4.17 void a pending -> 409', r.status === 409 && isErr(r), `${r.status} ${r.text}`)
r = await api('POST', `/api/payments/${pPend}/reject`, toks.manager, { reason: 'cleanup reject' }); rec('4.17b reject that pending -> 200', r.status === 200, `${r.status} ${r.text}`)
// h) over cap
s = await state()
r = await pay(toks.staff, { amountSen: s.cap + 1, method: 'cash', receivedAt: RA }); rec(`4.18 amount cap+1 (${s.cap + 1}) -> 422`, r.status === 422 && isErr(r), `${r.status} ${r.text}`)
// i) validation
const nw = IDS.nw
const bad = {
  'receivedAt no offset': { amountSen: 100, method: 'cash', receivedAt: '2026-10-20T10:00:00' },
  'receivedAt date only': { amountSen: 100, method: 'cash', receivedAt: '2026-10-20' },
  'receivedAt Feb 30': { amountSen: 100, method: 'cash', receivedAt: '2026-02-30T10:00:00+08:00' },
  'receivedAt garbage': { amountSen: 100, method: 'cash', receivedAt: 'yesterday' },
  'amount 0': { amountSen: 0, method: 'cash', receivedAt: RA },
  'amount -100': { amountSen: -100, method: 'cash', receivedAt: RA },
  'amount 1.5': { amountSen: 1.5, method: 'cash', receivedAt: RA },
  'amount "100"': { amountSen: '100', method: 'cash', receivedAt: RA },
  'method online': { amountSen: 100, method: 'online', receivedAt: RA },
  'method cheque': { amountSen: 100, method: 'cheque', receivedAt: RA },
  'bank_transfer no slip': { amountSen: 100, method: 'bank_transfer', receivedAt: RA },
  'slip in Beta folder': { amountSen: 100, method: 'bank_transfer', receivedAt: RA, slipPath: `${IDS.beta}/${IDS.lChen}/x.pdf` },
  'slip nonexistent NW': { amountSen: 100, method: 'bank_transfer', receivedAt: RA, slipPath: `${nw}/${L}/does-not-exist.pdf` },
  'slip traversal': { amountSen: 100, method: 'bank_transfer', receivedAt: RA, slipPath: `${nw}/../${IDS.beta}/x.pdf` },
}
for (const [k, b] of Object.entries(bad)) { r = await pay(toks.staff, b); rec(`4.19 invalid (${k}) -> 400`, r.status === 400 && isErr(r), `${r.status} ${r.text}`) }
// j) bank transfer with real slip
const pdf = Buffer.from('%PDF-1.4\n1 0 obj<</Type/Catalog/Pages 2 0 R>>endobj\n2 0 obj<</Type/Pages/Kids[3 0 R]/Count 1>>endobj\n3 0 obj<</Type/Page/Parent 2 0 R/MediaBox[0 0 612 792]>>endobj\ntrailer<</Root 1 0 R>>\n%%EOF\n')
const stamp = Date.now()
const slip = `${nw}/${L}/grader-${stamp}.pdf`
let up = await clients.staff.storage.from('payment-slips').upload(slip, pdf, { contentType: 'application/pdf' })
rec('4.20 staff uploads PDF slip to NW folder', !up.error, up.error?.message ?? slip)
if (!up.error) uploaded.push(slip)
const fake = `${nw}/${L}/grader-fake-${stamp}.pdf`
up = await clients.staff.storage.from('payment-slips').upload(fake, Buffer.from('this is not a pdf at all'), { contentType: 'application/pdf' })
if (!up.error) uploaded.push(fake)
console.log('INFO upload of fake pdf bytes:', up.error?.message ?? 'accepted by storage')
if (!up.error) { r = await pay(toks.staff, { amountSen: 100, method: 'bank_transfer', receivedAt: RA, slipPath: fake }); rec('4.21 slip with non-PDF bytes -> 400', r.status === 400 && isErr(r), `${r.status} ${r.text}`) }
const big = `${nw}/${L}/grader-big-${stamp}.pdf`
up = await clients.staff.storage.from('payment-slips').upload(big, Buffer.concat([pdf, Buffer.alloc(5 * 1024 * 1024 + 10, 32)]), { contentType: 'application/pdf' })
if (!up.error) uploaded.push(big)
rec('4.22 >5MB slip upload refused (by storage) or payment refused', !!up.error || (await pay(toks.staff, { amountSen: 100, method: 'bank_transfer', receivedAt: RA, slipPath: big })).status === 400, up.error?.message ?? 'storage accepted')
const txt = `${nw}/${L}/grader-${stamp}.txt`
up = await clients.staff.storage.from('payment-slips').upload(txt, Buffer.from('hello'), { contentType: 'text/plain' })
if (!up.error) uploaded.push(txt)
rec('4.23 text/plain upload refused by bucket or payment refuses it', !!up.error || (await pay(toks.staff, { amountSen: 100, method: 'bank_transfer', receivedAt: RA, slipPath: txt })).status === 400, up.error?.message ?? 'storage accepted')
r = await pay(toks.staff, { amountSen: 5000, method: 'bank_transfer', receivedAt: '2026-10-20T00:30:00+08:00', slipPath: slip })
rec('4.24 bank_transfer with real slip -> 201 pending', r.status === 201 && r.json?.status === 'pending_verification', `${r.status} ${r.text}`)
const pBank = r.json?.id
r = await pay(toks.staff, { amountSen: 5000, method: 'bank_transfer', receivedAt: RA, slipPath: slip }); console.log('INFO reuse same slip for 2nd payment ->', r.status, r.text)
if (r.status === 201) { await api('POST', `/api/payments/${r.json.id}/reject`, toks.manager, { reason: 'grader cleanup' }) }
const row = (await rest('GET', `payments?select=slip_path,received_at,status&id=eq.${pBank}`, toks.manager)).json?.[0]
rec('4.25 stored slip_path and received_at', row?.slip_path === slip && Date.parse(row?.received_at) === Date.parse('2026-10-20T00:30:00+08:00'), JSON.stringify(row))
const g = await get()
rec('4.26 GET shows receivedAt as +08:00 instant', g.payments.find(p => p.id === pBank)?.receivedAt === '2026-10-20T00:30:00+08:00', g.payments.find(p => p.id === pBank)?.receivedAt)
r = await api('POST', `/api/payments/${pBank}/approve`, toks.manager, {}); rec('4.27 approve bank transfer -> 200', r.status === 200 && r.json?.status === 'approved', `${r.status} ${r.text}`)
// receivedAt with Z accepted
r = await pay(toks.staff, { amountSen: 100, method: 'cash', receivedAt: '2026-10-19T16:30:00Z' }); rec('4.28 receivedAt with Z offset -> 201', r.status === 201, `${r.status} ${r.text}`)
if (r.status === 201) { await api('POST', `/api/payments/${r.json.id}/reject`, toks.manager, { reason: 'grader cleanup' }) }
// manager-recorded bank transfer approved immediately
const slip2 = `${nw}/${L}/grader2-${stamp}.pdf`
up = await clients.manager.storage.from('payment-slips').upload(slip2, pdf, { contentType: 'application/pdf' })
if (!up.error) uploaded.push(slip2)
r = await pay(toks.manager, { amountSen: 1000, method: 'bank_transfer', receivedAt: RA, slipPath: slip2 }); rec('4.29 manager bank_transfer -> 201 approved', r.status === 201 && r.json?.status === 'approved', `${r.status} ${r.text}`)
s = await state()
console.log('STATE', JSON.stringify({ total: s.total, paid: s.paid, pending: s.pending }))
writeFileSync('zz-grader-uploaded.json', JSON.stringify(uploaded))
writeFileSync('zz-grader-t4ids.json', JSON.stringify({ pMgr, pStaff, pRej, pPend, pBank, slip }))

