  const jar = new Map()
  const c = createServerClient(SB, PK, { cookies: { getAll: () => [...jar].map(([name, value]) => ({ name, value })), setAll: list => { for (const { name, value } of list) { if (value) jar.set(name, value); else jar.delete(name) } } } })
