  const body = { ...fields, x_signature: sig ?? sign(fields) }
  if (sig === null) delete body.x_signature
  const r = await fetch(APP + '/api/webhooks/gateway', { method: 'POST', headers: { 'content-type': 'application/x-www-form-urlencoded' }, body: raw ?? new URLSearchParams(body) })
  const text = await r.text(); let json; try { json = JSON.parse(text) } catch {}
  return { status: r.status, text: text.slice(0, 200), json }
}
EOF
