import { login, api, rest, rec, IDS, isErr, sign, hook, cookieLogin, page } from './zz-grader-lib.mjs'
import { execFileSync } from 'node:child_process'
import { writeFileSync } from 'node:fs'
const { toks } = await login()
const L = IDS.lProbe
const vec = { id: 'bill_8f3a2c', paid: 'true', paid_amount: '210050', paid_at: '2026-04-01 00:30:12 +0800', transaction_id: 'TX-000123', transaction_status: 'completed' }
rec('5.0 grader signer matches brief test vector', sign(vec) === '06994fab2d674e7829144eaa2204631716d3c099b503d38945e92b6296531641')
const bill = async id => (await rest('GET', `gateway_bills?select=id,status,amount_sen,lease_id&id=eq.${id}`, toks.manager)).json?.[0]
const paysFor = async id => (await rest('GET', `payments?select=id,status,method,amount_sen,unapplied_sen,received_at,gateway_bill_id&gateway_bill_id=eq.${id}`, toks.manager)).json
const lease = async id => (await api('GET', `/api/leases/${id}`, toks.manager)).json
const dueNow = j => j.invoices.filter(i => i.dueDate <= '2026-10-20').reduce((s, i) => s + i.amountSen - i.paidSen, 0)
const fields = (id, amt, paid = 'true', paidAt = '2026-10-20 11:22:33 +0800') => ({ id, paid, paid_amount: paid === 'true' ? String(amt) : '0', paid_at: paidAt, transaction_id: `TX-G-${Math.random().toString(36).slice(2)}`, transaction_status: paid === 'true' ? 'completed' : 'failed' })

let j = await lease(L)
const expectDue = dueNow(j)
// pending staff payment for approve-time recheck
let r = await api('POST', `/api/leases/${L}/payments`, toks.staff, { amountSen: 900000, method: 'cash', receivedAt: '2026-10-20T09:00:00+08:00' })
rec('5.1 staff pending 900000 recorded', r.status === 201 && r.json?.status === 'pending_verification', `${r.status} ${r.text}`)
const pP = r.json?.id
r = await api('POST', `/api/leases/${L}/gateway-bills`, toks.probe)
rec(`5.2 probe creates bill -> 201 {billId, amountSen=${expectDue}}`, r.status === 201 && r.json?.amountSen === expectDue && typeof r.json?.billId === 'string' && Object.keys(r.json).length === 2, `${r.status} ${r.text}`)
const B1 = r.json?.billId
rec('5.3 billId unguessable (>=20 chars, not sequential)', typeof B1 === 'string' && B1.length >= 20 && /[a-zA-Z0-9_-]{20,}/.test(B1), B1)
r = await api('POST', `/api/leases/${L}/gateway-bills`, toks.aisyah); rec('5.4 aisyah on probe lease -> 404', r.status === 404 && isErr(r), `${r.status} ${r.text}`)
r = await api('POST', `/api/leases/${L}/gateway-bills`, toks.staff); rec('5.5 staff -> 403', r.status === 403 && isErr(r), `${r.status} ${r.text}`)
r = await api('POST', `/api/leases/${L}/gateway-bills`, toks.manager); rec('5.5b manager -> 403', r.status === 403 && isErr(r), `${r.status} ${r.text}`)
// error paths
r = await hook(fields(B1, expectDue + 1)); rec('5.6 wrong paid_amount -> 422', r.status === 422, `${r.status} ${r.text}`)
r = await hook(fields(B1, expectDue - 1)); rec('5.6b paid_amount 1 sen short -> 422', r.status === 422, `${r.status} ${r.text}`)
rec('5.7 bill still pending after 422, no payment', (await bill(B1))?.status === 'pending' && (await paysFor(B1)).length === 0, JSON.stringify(await bill(B1)))
r = await hook(fields(B1, expectDue), { sig: 'a'.repeat(64) }); rec('5.8 forged signature -> 401', r.status === 401, `${r.status} ${r.text}`)
r = await hook(fields(B1, expectDue), { sig: null }); rec('5.9 missing signature -> 401', r.status === 401, `${r.status} ${r.text}`)
const f0 = fields(B1, expectDue); r = await hook(f0, { sig: sign(f0, 'wrong_key') }); rec('5.10 signature with wrong key -> 401', r.status === 401, `${r.status} ${r.text}`)
const f1 = fields(B1, expectDue); const s1 = sign(f1); r = await hook({ ...f1, paid_amount: '1' }, { sig: s1 }); rec('5.11 tampered field after signing -> 401', r.status === 401, `${r.status} ${r.text}`)
const f2 = fields(B1, expectDue); r = await hook({ ...f2, extra: 'unsigned' }, { sig: sign(f2) }); rec('5.12 extra field not covered by signature -> 401', r.status === 401, `${r.status} ${r.text}`)
r = await hook(fields('bill_does_not_exist_' + Date.now(), 100)); rec('5.13 unknown bill (signed) -> 404', r.status === 404, `${r.status} ${r.text}`)
r = await hook(fields('00000000-0000-4000-8000-000000000000', 100)); rec('5.13b unknown uuid bill (signed) -> 404', r.status === 404, `${r.status} ${r.text}`)
r = await fetch('http://localhost:3000/api/webhooks/gateway', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(f2) }); rec('5.13c JSON body (unsigned) -> 4xx not 5xx', r.status >= 400 && r.status < 500, String(r.status))
rec('5.14 still pending, no payment after all rejected callbacks', (await bill(B1))?.status === 'pending' && (await paysFor(B1)).length === 0)
// valid paid with extra signed field
const paidAt = '2026-10-20 11:22:33 +0800'
const fx = { ...fields(B1, expectDue, 'true', paidAt), currency: 'MYR', zz_future: 'x y' }
r = await hook(fx); rec('5.15 valid paid (+ extra signed fields) -> 200', r.status === 200, `${r.status} ${r.text}`)
let ps = await paysFor(B1)
rec('5.16 exactly one approved online payment, received_at = paid_at, unapplied 0', (await bill(B1))?.status === 'paid' && ps.length === 1 && ps[0].status === 'approved' && ps[0].method === 'online' && ps[0].amount_sen === expectDue && Date.parse(ps[0].received_at) === Date.parse('2026-10-20T11:22:33+08:00') && ps[0].unapplied_sen === 0, JSON.stringify(ps))
j = await lease(L)
rec('5.17 due-now invoices now fully paid', dueNow(j) === 0, `dueNow=${dueNow(j)}`)
const sim = execFileSync('node', ['scripts/gateway-sim.mjs', B1, String(expectDue)], { env: { ...process.env, GATEWAY_X_SIGNATURE_KEY: 'test_x_signature_key' } }).toString().trim()
rec('5.18 simulator repeat -> 200, no new payment', sim.startsWith('200') && (await paysFor(B1)).length === 1, sim)
r = await hook(fields(B1, 0, 'false')); rec('5.19 paid=false after paid -> 200, still paid', r.status === 200 && (await bill(B1))?.status === 'paid' && (await paysFor(B1)).length === 1, `${r.status} ${r.text}`)
r = await hook(fields(B1, expectDue + 5)); rec('5.19b paid=true wrong amount on already-paid bill -> 422 or 200, no effect', [200, 422].includes(r.status) && (await paysFor(B1)).length === 1, `${r.status} ${r.text}`)
// approve-time recheck
r = await api('POST', `/api/payments/${pP}/approve`, toks.manager, {}); rec('5.20 approve pending 900000 when remaining is 800000 -> 422', r.status === 422 && isErr(r), `${r.status} ${r.text}`)
j = await lease(L)
rec('5.21 payment left pending after 422', j.payments.find(p => p.id === pP)?.status === 'pending_verification', j.payments.find(p => p.id === pP)?.status)
await api('POST', `/api/payments/${pP}/reject`, toks.manager, { reason: 'grader cleanup' })
r = await api('POST', `/api/leases/${L}/gateway-bills`, toks.probe); rec('5.22 nothing due -> 422', r.status === 422 && isErr(r), `${r.status} ${r.text}`)
// past lease on D-03-2 for more bills
r = await api('POST', '/api/leases', toks.manager, { unitId: IDS.unitD, tenantId: IDS.tProbe, startDate: '2025-01-01', endDate: '2025-06-30', monthlyRentSen: 100000, depositSen: 0 })
rec('5.23 past lease for probe on D-03-2 -> 201', r.status === 201, `${r.status} ${r.text}`)
const LP = r.json?.id
const mk = async () => (await api('POST', `/api/leases/${LP}/gateway-bills`, toks.probe)).json
const [BR, B2, B3, B5] = [await mk(), await mk(), await mk(), await mk()]
rec('5.24 four bills on past lease, each 600000, distinct ids', [BR, B2, B3, B5].every(b => b?.amountSen === 600000) && new Set([BR, B2, B3, B5].map(b => b?.billId)).size === 4, JSON.stringify([BR, B2, B3, B5]))
// return page
const ck = await cookieLogin('probe')
let pg = await page(`/payments/return?bill_id=${BR.billId}&paid=true`, ck)
rec('5.25 /payments/return as probe renders 200', pg.status === 200, `${pg.status} ${pg.location ?? ''}`)
console.log('INFO return page mentions pending:', /pending/i.test(pg.html), ' mentions paid:', />\s*paid\s*</i.test(pg.html))
pg = await page(`/payments/return?bill_id=${BR.billId}&paid=true`)
console.log('INFO return page signed-out:', pg.status, pg.location)
const ckA = await cookieLogin('aisyah')
pg = await page(`/payments/return?bill_id=${BR.billId}&paid=true`, ckA)
console.log('INFO return page as aisyah (other tenant\'s bill):', pg.status, 'contains amount 6,000.00:', pg.html.includes('6,000.00'))
rec('5.26 return URL did not settle the bill or create a payment', (await bill(BR.billId))?.status === 'pending' && (await paysFor(BR.billId)).length === 0 && (await lease(LP)).invoices.every(i => i.paidSen === 0), JSON.stringify(await bill(BR.billId)))
// concurrency: 10 identical paid callbacks
const f10 = fields(B2.billId, 600000)
const rs = await Promise.all(Array.from({ length: 10 }, () => hook(f10)))
rec('5.27 10 concurrent identical paid callbacks -> all 200, exactly one payment', rs.every(x => x.status === 200) && (await paysFor(B2.billId)).length === 1 && (await bill(B2.billId))?.status === 'paid', rs.map(x => x.status).join(','))
j = await lease(LP)
rec('5.28 past lease fully paid once', j.invoices.every(i => i.paidSen === i.amountSen && i.status === 'paid'), j.invoices.map(i => i.paidSen).join(','))
// failed then paid
r = await hook(fields(B3.billId, 0, 'false')); rec('5.29 paid=false on pending -> 200, bill failed', r.status === 200 && (await bill(B3.billId))?.status === 'failed', `${r.status} ${r.text}`)
r = await hook(fields(B3.billId, 0, 'false')); rec('5.30 paid=false repeat on failed -> 200, still failed, no payment', r.status === 200 && (await bill(B3.billId))?.status === 'failed' && (await paysFor(B3.billId)).length === 0, `${r.status} ${r.text}`)
r = await hook(fields(B3.billId, 600001)); rec('5.31 wrong amount on failed bill -> 422, still failed', r.status === 422 && (await bill(B3.billId))?.status === 'failed', `${r.status} ${r.text}`)
r = await hook(fields(B3.billId, 600000)); ps = await paysFor(B3.billId)
rec('5.32 paid=true after failed -> 200, paid, one payment fully unapplied (600000)', r.status === 200 && (await bill(B3.billId))?.status === 'paid' && ps.length === 1 && ps[0].unapplied_sen === 600000, `${r.status} ${JSON.stringify(ps)}`)
// mixed concurrent out-of-order
const mixed = [...Array.from({ length: 5 }, () => fields(B5.billId, 600000)), ...Array.from({ length: 5 }, () => fields(B5.billId, 0, 'false'))]
const rm = await Promise.all(mixed.map(f => hook(f)))
ps = await paysFor(B5.billId)
rec('5.33 5 paid + 5 failed concurrently -> all 200, bill paid, exactly one payment', rm.every(x => x.status === 200) && (await bill(B5.billId))?.status === 'paid' && ps.length === 1, `${rm.map(x => x.status).join(',')} bill=${(await bill(B5.billId))?.status} payments=${ps.length}`)
const lj = await lease(LP)
rec('5.34 GET shows online payments with unappliedSen', lj.payments.filter(p => p.method === 'online').length === 3 && lj.payments.filter(p => p.unappliedSen === 600000).length === 2, JSON.stringify(lj.payments))
// bill on a lease whose invoices fully paid -> 422
r = await api('POST', `/api/leases/${LP}/gateway-bills`, toks.probe); rec('5.35 bill on fully paid past lease -> 422', r.status === 422, `${r.status} ${r.text}`)
// future lease: nothing due -> 422
const created = JSON.parse((await import('node:fs')).readFileSync('zz-grader-created.json', 'utf8'))
r = await api('POST', `/api/leases/${created[0]}/gateway-bills`, toks.probe); rec('5.36 bill on future lease (nothing due today) -> 422', r.status === 422, `${r.status} ${r.text}`)
writeFileSync('zz-grader-t5ids.json', JSON.stringify({ B1, BR: BR.billId, B2: B2.billId, B3: B3.billId, B5: B5.billId, LP }))

import { cookieLogin, page } from './zz-grader-lib.mjs'
import { readFileSync } from 'node:fs'
const { BR, B2 } = JSON.parse(readFileSync('zz-grader-t5ids.json', 'utf8'))
const strip = h => h.replace(/<script[\s\S]*?<\/script>/g, '').replace(/<style[\s\S]*?<\/style>/g, '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ')
for (const [label, ck, id] of [['signed-out BR', null, BR], ['probe BR', await cookieLogin('probe'), BR], ['probe B2 (paid)', await cookieLogin('probe'), B2], ['aisyah BR', await cookieLogin('aisyah'), BR], ['staff BR', await cookieLogin('staff'), BR]]) {
  const p = await page(`/payments/return?bill_id=${id}&paid=true`, ck)
  const t = strip(p.html)
  const i = t.search(/bill|payment/i)
  console.log(`--- ${label}: ${p.status} ${p.location ?? ''}\n${t.slice(Math.max(0, i - 100), i + 500)}`)
}

