for (const t of tables) {
  const r = await rest('GET', `${t}?select=*`, undefined)
  rec(`6.1 anon GET ${t} -> nothing`, (Array.isArray(r.json) && r.json.length === 0) || r.status === 401 || r.status === 403, `${r.status} ${r.text.slice(0, 100)}`)
}
for (const fn of ['manager_org_id', 'member_org_id', 'tenant_lease_ids', 'payments_slip_exists', 'require_auth_user', 'current_role', 'allocate_payment', 'approve_payment', 'record_payment', 'create_lease']) {
  for (const who of ['anon', 'manager']) {
    const r = await rest('POST', `rpc/${fn}`, who === 'anon' ? undefined : toks.manager, {})
    rec(`6.2 ${who} POST /rpc/${fn} -> refused`, r.status >= 400, `${r.status} ${r.text.slice(0, 90)}`)
  }
}
const ro = await fetch(`${SB}/rest/v1/`, { headers: { apikey: PK } }); const roj = await ro.json().catch(() => ({}))
console.log('INFO anon OpenAPI paths:', ro.status, Object.keys(roj.paths ?? {}).join(','))
// anon writes
for (const t of tables) { const r = await rest('POST', t, undefined, { name: 'x' }); rec(`6.3 anon INSERT ${t} refused`, r.status >= 400, `${r.status}`) }
// tenant counts
const count = async (who, t) => { const r = await rest('GET', `${t}?select=*`, toks[who]); return Array.isArray(r.json) ? r.json : { err: r.status } }
const expA = { organizations: 1, memberships: 0, units: 1, tenants: 1, leases: 1, invoices: 7, payments: 2, payment_allocations: 3, gateway_bills: 0, audit_log: 0 }
for (const t of tables) { const rows = await count('aisyah', t); rec(`6.4 aisyah sees ${expA[t]} ${t}`, Array.isArray(rows) ? rows.length === expA[t] : expA[t] === 0, Array.isArray(rows) ? `${rows.length}` : JSON.stringify(rows)) }
const aT = await count('aisyah', 'tenants'); rec('6.4b aisyah tenant row is her own', aT[0]?.id === IDS.tAisyah, aT[0]?.id)
const aU = await count('aisyah', 'units'); rec('6.4c aisyah unit is A-12-3', aU[0]?.id === IDS.unitA, aU[0]?.name)
const expC = { organizations: 1, memberships: 0, units: 1, tenants: 1, leases: 1, invoices: 13, payments: 0, payment_allocations: 0, gateway_bills: 0, audit_log: 0 }
for (const t of tables) { const rows = await count('chen', t); rec(`6.5 chen sees ${expC[t]} ${t}`, Array.isArray(rows) ? rows.length === expC[t] : expC[t] === 0, Array.isArray(rows) ? `${rows.length}` : JSON.stringify(rows)) }
const pl = await count('probe', 'leases'); rec('6.5b probe sees only own leases (C-01-7 + D-03-2 ones)', pl.every(l => l.tenant_id === IDS.tProbe) && pl.length >= 1, `${pl.length}`)
const pu = await count('probe', 'units'); rec('6.5c probe sees units C-01-7 and D-03-2 only', pu.length === 2 && pu.every(u => [IDS.unitC, IDS.unitD].includes(u.id)), pu.map(u => u.name).join(','))
// staff / manager scope
for (const who of ['staff', 'manager']) {
  for (const t of tables.filter(t => t !== 'audit_log')) {
    const rows = await count(who, t)
    rec(`6.6 ${who} ${t}: own org only`, Array.isArray(rows) && rows.length > 0 && rows.every(x => (x.org_id ?? x.id) === IDS.nw), Array.isArray(rows) ? `${rows.length}` : JSON.stringify(rows))
  }
}
const sa = await count('staff', 'audit_log'); rec('6.7 staff sees no audit_log', !Array.isArray(sa) || sa.length === 0, Array.isArray(sa) ? `${sa.length}` : JSON.stringify(sa))
const ma = await count('manager', 'audit_log')
rec('6.8 manager audit_log own org only', Array.isArray(ma) && ma.length > 0 && ma.every(x => x.org_id === IDS.nw), `${ma.length}`)
const actions = [...new Set(ma.map(x => x.action))]
console.log('INFO NW audit actions:', actions.join(','), 'sample:', JSON.stringify(ma.find(x => x.entity_id === t4.pStaff)))
const has = (act, ent) => ma.some(x => x.action.toLowerCase().includes(act) && (!ent || x.entity_id === ent) && x.actor_id && x.created_at && x.details != null)
rec('6.9 audit rows: lease created (probe past lease), approve, reject, void, with actor/details/created_at', has('lease', t5.LP) && has('approv', t4.pStaff) && has('reject', t4.pRej) && has('void', t4.pMgr), actions.join(','))
const mgrUid = ma.find(x => x.entity_id === t4.pStaff && /approv/i.test(x.action))?.actor_id
const { data: mu } = await clients.manager.auth.getUser()
rec('6.9b approval actor_id is the manager user', mgrUid === mu.user.id, `${mgrUid} vs ${mu.user.id}`)
rec('6.9c seed approvals audited (Aisyah bank transfer approval)', has('approv', IDS.pBank), '')
const ba = await count('beta', 'audit_log'); rec('6.10 beta manager audit_log: only Beta rows', Array.isArray(ba) && ba.every(x => x.org_id === IDS.beta), Array.isArray(ba) ? `${ba.length}` : JSON.stringify(ba))
for (const t of ['organizations','memberships','units','tenants','leases','invoices','payments','payment_allocations','gateway_bills']) {
  const rows = await count('beta', t); rec(`6.10b beta ${t}: none from Northwind`, Array.isArray(rows) && rows.every(x => (x.org_id ?? x.id) === IDS.beta), Array.isArray(rows) ? `${rows.length}` : '')
}
// tenant phone
const probeT = (await count('probe', 'tenants'))[0]
const orig = probeT.phone
let r = await rest('PATCH', `tenants?id=eq.${IDS.tProbe}`, toks.probe, { phone: '+60 12-345 6789' }, 'return=representation')
rec('6.11 probe PATCH own phone -> ok, 1 row', r.status < 300 && Array.isArray(r.json) && r.json.length === 1 && r.json[0].phone === '+60 12-345 6789', `${r.status} ${r.text.slice(0, 120)}`)
r = await rest('PATCH', `tenants?id=eq.${IDS.tProbe}`, toks.probe, { full_name: 'Hacked' }, 'return=representation'); rec('6.12 probe PATCH own full_name refused', r.status >= 400 || (Array.isArray(r.json) && r.json.length === 0), `${r.status} ${r.text.slice(0, 120)}`)
r = await rest('PATCH', `tenants?id=eq.${IDS.tProbe}`, toks.probe, { email: 'x@y.z' }, 'return=representation'); rec('6.12b probe PATCH own email refused', r.status >= 400 || (Array.isArray(r.json) && r.json.length === 0), `${r.status} ${r.text.slice(0, 120)}`)
r = await rest('PATCH', `tenants?id=eq.${IDS.tProbe}`, toks.probe, { org_id: IDS.beta }, 'return=representation'); rec('6.12c probe PATCH own org_id refused', r.status >= 400 || (Array.isArray(r.json) && r.json.length === 0), `${r.status} ${r.text.slice(0, 120)}`)
r = await rest('PATCH', `tenants?id=eq.${IDS.tProbe}`, toks.probe, { user_id: '00000000-0000-4000-8000-000000000000' }, 'return=representation'); rec('6.12d probe PATCH own user_id refused', r.status >= 400 || (Array.isArray(r.json) && r.json.length === 0), `${r.status} ${r.text.slice(0, 120)}`)
r = await rest('PATCH', `tenants?id=eq.${IDS.tAisyah}`, toks.probe, { phone: '000' }, 'return=representation'); rec('6.13 probe PATCH aisyah phone -> 0 rows/refused', r.status >= 400 || (Array.isArray(r.json) && r.json.length === 0), `${r.status} ${r.text.slice(0, 120)}`)
r = await rest('PATCH', `tenants?id=eq.${IDS.tProbe}`, toks.staff, { phone: orig }, 'return=representation'); rec('6.13b staff PATCH tenant phone refused', r.status >= 400 || (Array.isArray(r.json) && r.json.length === 0), `${r.status} ${r.text.slice(0, 120)}`)
r = await rest('PATCH', `tenants?id=eq.${IDS.tProbe}`, toks.probe, { phone: orig }, 'return=representation'); console.log('INFO restore probe phone', r.status)
// no writes anywhere (insert / update same-value / delete) for staff, manager, probe
const targets = {
  organizations: ['id', IDS.nw, { name: 'Northwind Properties' }],
  memberships: ['org_id', IDS.nw, { role: 'manager' }],
  units: ['id', IDS.unitD, { name: 'D-03-2' }],
  tenants: ['id', IDS.tProbe, { full_name: 'Probe Tenant' }],
  leases: ['id', t5.LP, { deposit_sen: 0 }],
  invoices: ['lease_id', t5.LP, { amount_sen: 100000 }],
  payments: ['id', t4.pMgr, { status: 'voided' }],
  payment_allocations: ['payment_id', t4.pStaff, { org_id: IDS.nw }],
  gateway_bills: ['id', t5.BR, { status: 'pending' }],
  audit_log: ['entity_id', t5.LP, { org_id: IDS.nw }],
}
for (const who of ['manager', 'staff', 'probe']) {
  for (const [t, [col, val, patch]] of Object.entries(targets)) {
    if (who === 'probe' && t === 'tenants') continue
    const ins = await rest('POST', t, toks[who], { org_id: IDS.nw, name: 'zz' }, 'return=representation')
    const up = await rest('PATCH', `${t}?${col}=eq.${val}`, toks[who], patch, 'return=representation')
    const del = await rest('DELETE', `${t}?${col}=eq.${val}`, toks[who], undefined, 'return=representation')
    const refused = x => x.status >= 400 || (Array.isArray(x.json) && x.json.length === 0)
    rec(`6.14 ${who} cannot INSERT/UPDATE/DELETE ${t}`, refused(ins) && refused(up) && refused(del), `ins ${ins.status} ${ins.text.slice(0, 60)} | upd ${up.status} ${up.text.slice(0, 60)} | del ${del.status} ${del.text.slice(0, 60)}`)
  }
}
// audit_log append-only for service role
const svc = admin()
const { data: arow } = await svc.from('audit_log').select('*').eq('entity_id', t5.LP).limit(1)
const ue = await svc.from('audit_log').update({ action: arow[0].action }).eq('id', arow[0].id).select()
rec('6.15 service role cannot UPDATE audit_log', !!ue.error || (ue.data ?? []).length === 0, ue.error?.message ?? JSON.stringify(ue.data))
const de = await svc.from('audit_log').delete().eq('id', arow[0].id).select()
rec('6.16 service role cannot DELETE audit_log', !!de.error || (de.data ?? []).length === 0, de.error?.message ?? JSON.stringify(de.data))
// storage
const seededSlip = `${IDS.nw}/${IDS.lAisyah}/ba2618e9-c760-4347-90ac-5b7f4b99140c.pdf`
const anonC = createClient(SB, PK, { auth: { persistSession: false } })
const st = c => c.storage.from('payment-slips')
const pdf = Buffer.from('%PDF-1.4\n%%EOF\n')
for (const [who, c] of [['anon', anonC], ['aisyah', clients.aisyah], ['probe', clients.probe], ['beta', clients.beta], ['chen', clients.chen]]) {
  const ls1 = await st(c).list(IDS.nw); const ls2 = await st(c).list(`${IDS.nw}/${IDS.lAisyah}`)
  const dl = await st(c).download(seededSlip)
  const sg = await st(c).createSignedUrl(seededSlip, 60)
  const upPath = `${IDS.nw}/${IDS.lProbe}/zz-${who}-${Date.now()}.pdf`
  const up = await st(c).upload(upPath, pdf, { contentType: 'application/pdf' })
  if (!up.error) uploaded.push(upPath)
  rec(`6.17 storage ${who}: cannot list/download/sign/upload NW slips`, (ls1.error || ls1.data.length === 0) && (ls2.error || ls2.data.length === 0) && !!dl.error && !!sg.error && !!up.error, `list=${ls1.data?.length ?? ls1.error?.message}/${ls2.data?.length ?? ls2.error?.message} dl=${dl.error ? 'err' : 'OK!'} sign=${sg.error ? 'err' : 'OK!'} up=${up.error ? 'err' : 'OK!'}`)
}
const pub = await fetch(`${SB}/storage/v1/object/public/payment-slips/${seededSlip}`); rec('6.18 public URL of slip refused', pub.status >= 400, String(pub.status))
for (const who of ['staff', 'manager']) {
  const sg = await st(clients[who]).createSignedUrl(seededSlip, 60)
  let ok = !sg.error
  let detail = sg.error?.message ?? ''
  if (ok) { const f = await fetch(sg.data.signedUrl); const b = Buffer.from(await f.arrayBuffer()); ok = f.status === 200 && b.subarray(0, 5).toString() === '%PDF-'; detail = `${f.status} ${b.length}B` }
  rec(`6.19 ${who} can create signed URL for NW slip and fetch it`, ok, detail)
  const ls = await st(clients[who]).list(`${IDS.nw}/${IDS.lAisyah}`); console.log(`INFO ${who} list NW lease folder:`, ls.error?.message ?? ls.data.length)
  const bup = await st(clients[who]).upload(`${IDS.beta}/${IDS.lChen}/zz-${who}.pdf`, pdf, { contentType: 'application/pdf' })
  if (!bup.error) uploaded.push(`${IDS.beta}/${IDS.lChen}/zz-${who}.pdf`)
  rec(`6.20 ${who} cannot upload into Beta folder`, !!bup.error, bup.error?.message ?? 'UPLOADED')
  const rup = await st(clients[who]).upload(`zz-root-${who}.pdf`, pdf, { contentType: 'application/pdf' })
  if (!rup.error) uploaded.push(`zz-root-${who}.pdf`)
  rec(`6.21 ${who} cannot upload outside an org folder`, !!rup.error, rup.error?.message ?? 'UPLOADED')
}
const bs = await st(clients.beta).createSignedUrl(seededSlip, 60); rec('6.22 beta manager cannot sign NW slip', !!bs.error, bs.error?.message ?? 'SIGNED')
const del = await st(clients.staff).remove([seededSlip]); const still = await st(clients.staff).createSignedUrl(seededSlip, 60)
console.log('INFO staff remove seeded slip:', JSON.stringify(del.data), del.error?.message, '| still exists:', !still.error)
rec('6.23 staff cannot delete an existing slip', !still.error, '')
const ow = await st(clients.staff).upload(seededSlip, pdf, { contentType: 'application/pdf', upsert: true }); rec('6.24 staff cannot overwrite an existing slip (upsert)', !!ow.error, ow.error?.message ?? 'OVERWRITTEN')
writeFileSync('zz-grader-uploaded.json', JSON.stringify(uploaded))

