const pdf = Buffer.from('%PDF-1.4\n%%EOF\n')
for (const [who, c] of [['anon', anonC], ['aisyah', clients.aisyah], ['probe', clients.probe], ['beta', clients.beta], ['chen', clients.chen]]) {
