cat > zz-grader-t9.mjs <<'EOF'
import { cookieLogin, page, rec, api, IDS, login } from './zz-grader-lib.mjs'
const ck = { manager: await cookieLogin('manager'), aisyah: await cookieLogin('aisyah') }
const srcs = new Set()
for (const [path, c] of [['/login'], ['/dashboard', ck.manager], [`/leases/${IDS.lAisyah}`, ck.manager], ['/leases/new', ck.manager], ['/portal', ck.aisyah]]) {
  const p = await page(path, c); for (const m of p.html.matchAll(/src="(\/_next\/static\/[^"]+\.js)"/g)) srcs.add(m[1])
  if (/sb_secret_|test_x_signature_key/.test(p.html)) console.log('LEAK in HTML', path)
}
let leak = []
for (const s of srcs) { const t = await (await fetch('http://localhost:3000' + s)).text(); if (/sb_secret_|N7UND0UgjKTVK|test_x_signature_key|SUPABASE_SECRET_KEY|service_role/.test(t)) leak.push(s) }
rec(`9.1 no secret key / gateway key in ${srcs.size} client JS chunks or HTML`, leak.length === 0, leak.join(','))
const { toks } = await login()
const j = (await api('GET', `/api/leases/${IDS.lAisyah}`, toks.aisyah)).json
rec('9.2 Aisyah lease unchanged at the end', JSON.stringify(j.invoices.map(i => i.paidSen)) === '[300000,150000,50000,0,0,0,0]' && j.payments.length === 2, j.invoices.map(i => i.paidSen).join(','))
const r = await api('GET', '/api/reports/collections?from=2026-01&to=2026-03', toks.manager)
rec('9.3 Northwind Jan-Mar report unchanged', r.text === '[{"month":"2026-01","collectedSen":300000},{"month":"2026-02","collectedSen":0},{"month":"2026-03","collectedSen":200000}]', r.text)
EOF
node zz-grader-t9.mjs 2>&1

